#!/bin/bash
# set-accent-color.sh - the GTK accent colour (Knomadic: GTK Colors / Titlebars > Accent). One hex value, replaced everywhere it appears in the
# GTK3/GTK4 files below (gtk-4.0/gtk.css hardcodes the resolved hex in ~130 places, so this is a full-file replace keyed on the CURRENT
# @define-color accent_bg_color, safe to re-run), plus the nearest GNOME accent preset for apps that only read the portal setting.
#
# SCOPE (narrowed 2026-10-17): GTK only. It no longer touches Qt/KDE files (kdeglobals + bluegrey.colors are generated by
# fm-tweaks from the Thunar swatches) and no longer leaves .bak-pre-* copies. Thunar / SMPlayer / Text Editor have their own swatches.
#
# Usage: ./set-accent-color.sh <new-hex-color>
#        ./set-accent-color.sh --get   (print current hex, no changes)

set -euo pipefail

GTK4_CSS="$HOME/.config/gtk-4.0/gtk.css"

get_current() {
    grep -oP '(?<=@define-color accent_bg_color #)[0-9a-fA-F]{6}' "$GTK4_CSS" | head -1
}

if [ "${1:-}" == "--get" ]; then
    get_current
    exit 0
fi

if [ $# -ne 1 ]; then
    echo "Usage: $0 <new-hex-color>"
    exit 1
fi

NEW_HEX="${1#\#}"
NEW_HEX="${NEW_HEX,,}"

if ! [[ "$NEW_HEX" =~ ^[0-9a-f]{6}$ ]]; then
    echo "Error: '$1' doesn't look like a valid 6-digit hex color."
    exit 1
fi

if [ ! -f "$GTK4_CSS" ]; then
    echo "Error: $GTK4_CSS not found - can't detect current color."
    exit 1
fi

OLD_HEX=$(get_current)
OLD_HEX="${OLD_HEX,,}"

if [ -z "$OLD_HEX" ]; then
    echo "Error: couldn't find current accent_bg_color in $GTK4_CSS"
    exit 1
fi

if [ "$OLD_HEX" == "$NEW_HEX" ]; then
    echo "Current color is already #$NEW_HEX - nothing to do."
    exit 0
fi

echo "Changing #$OLD_HEX -> #$NEW_HEX"
echo

HEX_FILES=(
    "$GTK4_CSS"
    "$HOME/.config/gtk-3.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-3.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-3.0/gtk-dark.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-4.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-4.0/gtk-dark.css"
)

for f in "${HEX_FILES[@]}"; do
    if [ -f "$f" ]; then
        python3 "$HOME/.themes/machine-setup/replace_color_skip_fg.py" hex "$f" "$OLD_HEX" "$NEW_HEX"
        echo "  hex updated: $f"
    fi
done

# Best-effort nearest named preset for the gsettings accent-color portal key
PRESETS="blue:3584e4 teal:2190a4 green:3a944a yellow:c88800 orange:ed5b00 red:e62d42 pink:d56199 purple:9141ac slate:6f8396"
BEST_NAME=""
BEST_DIST=999999999
r1=$((16#${NEW_HEX:0:2})); g1=$((16#${NEW_HEX:2:2})); b1=$((16#${NEW_HEX:4:2}))
for entry in $PRESETS; do
    name="${entry%%:*}"
    hex="${entry##*:}"
    r2=$((16#${hex:0:2})); g2=$((16#${hex:2:2})); b2=$((16#${hex:4:2}))
    dist=$(( (r1-r2)*(r1-r2) + (g1-g2)*(g1-g2) + (b1-b2)*(b1-b2) ))
    if [ "$dist" -lt "$BEST_DIST" ]; then
        BEST_DIST=$dist
        BEST_NAME=$name
    fi
done
gsettings set org.gnome.desktop.interface accent-color "$BEST_NAME" 2>/dev/null && \
    echo "  gsettings accent-color (nearest preset): $BEST_NAME"

# the generated "no colour change when inactive" block copies literal values (e.g. the accent inside the switch gradient): regenerate it so it follows the new accent
if [ "$("$(dirname "$(readlink -f "$0")")/set-gtk-color.sh" inactive --get 2>/dev/null)" == "on" ]; then
    "$(dirname "$(readlink -f "$0")")/set-gtk-color.sh" inactive on | sed 's/^/  /'
    grep -q 'KNOMADIC: flat-surfaces BEGIN' "$HOME/.config/gtk-4.0/gtk.css" && "$(dirname "$(readlink -f "$0")")/set-flat-surfaces.sh" | sed 's/^/  /'   # flat surfaces stay the LAST block
fi

echo
echo "Done. Restart GTK apps to see the change - some may glitch on a live config swap, just reopen them."
